const $=s=>document.querySelector(s), app=$('#app'), dialog=$('#dialog');
const paths={bottle:'<path d="M9 3h6v4l3 4v10H6V11l3-4zM8 3h8M6 15h12"/>',gift:'<rect x="3" y="8" width="18" height="4" rx="1"/><path d="M5 12v9h14v-9M12 8v13M12 8C4 8 5 1 9 3l3 5c8 0 7-7 3-5z"/>',gem:'<path d="m3 8 4-5h10l4 5-9 13zM3 8h18M7 3l5 18L17 3"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M3 21c0-10 18-10 18 0z"/>',coin:'<circle cx="12" cy="12" r="9"/><path d="m12 6 1.8 3.6 4 .6-2.9 2.8.7 4-3.6-1.9-3.6 1.9.7-4L6.2 10.2l4-.6z"/>',home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',play:'<path d="m8 5 11 7-11 7z"/>',games:'<path d="M7 7h10c4 0 6 11 3 12-2 1-4-3-5-3H9c-1 0-3 4-5 3C1 18 3 7 7 7Z"/><path d="M7 10v4m-2-2h4m7-1h.01m2 3h.01"/>',trophy:'<path d="M8 3h8v7a4 4 0 0 1-8 0zM8 5H4v3q0 4 5 4m7-7h4v3q0 4-5 4M12 14v6m-4 1h8"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 8a2.5 2.5 0 0 1 5 0c0 2-2.5 2-2.5 4m0 4h.01"/>',settings:'<path d="m9 3-.5 3-2 1-3-.5-1.5 3 2.5 2v2L2 15l1.5 3 3-.5 2 1 .5 3h4l.5-3 2-1 3 .5 1.5-3-2.5-1.5v-2L22 9.5l-1.5-3-3 .5-2-1-.5-3z"/><circle cx="12" cy="12" r="3"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',external:'<path d="M14 4h6v6m0-6L10 14m0-10H4v16h16v-6"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',pause:'<path d="M8 5v14M16 5v14"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9z"/>',flame:'<path d="M12 3c1 5 7 6 7 12a7 7 0 1 1-14 0c0-3 2-6 4-8 0 4 1 5 2 5 2-2 1-5 1-9Z"/>',check:'<path d="m5 12 4 4L19 6"/>',leaf:'<path d="M20 4C8 2 2 8 5 15s15 4 15-11Z"/><path d="m4 20 11-11"/>',undo:'<path d="M8 5 3 10l5 5m-5-5h11a6 6 0 0 1 0 12"/>',restart:'<path d="M4 9a9 9 0 1 1-1 7m1-13v6h6"/>',volume:'<path d="M4 9h4l5-4v14l-5-4H4zM17 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>',flag:'<path d="M5 21V3m0 1h13l-3 5 3 5H5"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.star}</svg>`;
const vial=(tier=0)=>`<span class="vial vial-${tier%6}" aria-hidden="true"></span>`;
const mascot=()=>`<img class="mascot" src="assets/bottle-mascot.webp" alt="Happy Peak Haven bottle mascot">`;
const stars=()=>[1,2,3].map(()=>icon('star')).join('');
const escapeText=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const motionAllowed=()=>data.motion&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const fmt=n=>Number(n).toLocaleString('en-AU');
const localDay=(date=new Date())=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
const defaultData=()=>({version:1,xp:0,completed:[],best:{tower:0,merge:0,sort:0,blocks:0,mahjong:0},height:0,tier:1,perfects:0,games:0,sortLevel:1,sortWins:0,badges:[],days:[],daily:[],tutorials:[],sound:false,motion:!window.matchMedia('(prefers-reduced-motion: reduce)').matches});
function readData(){try{const parsed=JSON.parse(localStorage.getItem('ph-arcade-v1'));if(!parsed||parsed.version!==1)return defaultData();const data={...defaultData(),...parsed,best:{...defaultData().best,...parsed.best}};for(const k of ['xp','height','tier','perfects','games','sortLevel','sortWins'])data[k]=Number.isFinite(data[k])?Math.max(k==='sortLevel'||k==='tier'?1:0,Math.floor(data[k])):defaultData()[k];for(const k of Object.keys(data.best))data.best[k]=Number.isFinite(data.best[k])?Math.max(0,data.best[k]):0;for(const k of ['badges','days','daily','tutorials'])data[k]=Array.isArray(data[k])?data[k].filter(x=>typeof x==='string'):[];data.completed=Array.isArray(data.completed)?[...new Set(data.completed.filter(x=>Number.isInteger(x)&&x>=0&&x<MISSIONS.length))].sort((a,b)=>a-b):[];return data;}catch{return defaultData();}}
let mission=null,chapter=0,finishing=false;
let data=normalizeCollection(readData()), engine=null, active=null, sortState=null, view='home', helpGame='tower', cancelModal=()=>{}, modalReturn=null, audio=null, toastTimer;
const games={tower:{name:'Vial Tower',subtitle:'One tap. A little balance. A new personal best.',description:'Find your balance, one vial at a time.',tags:['One tap','Endless'],steps:['Watch the vial drift from side to side.','Tap or press Space to drop it onto the stack.','Land near the centre. Perfect drops earn bonus points.'],tip:'Take your time. A centred stack is a steady stack.',control:'Drop vial'},merge:{name:'Vial Merge',subtitle:'Small matches. Satisfying little chain reactions.',description:'Little matches. Lovely chain reactions.',tags:['Merge','Relaxing'],steps:['Move your pointer or drag to choose a spot.','Tap or press Drop vial to release it.','Match identical colours and numbers to make a bigger vial. Keep the pile below the line.'],tip:'Build pairs low in the jar and leave space for bigger vials.',control:'Drop vial'},sort:{name:'Lab Sort',subtitle:'A colourful puzzle, at your own pace.',description:'A little order. A lot of satisfaction.',tags:['Puzzle','No timer'],steps:['Select a tube, then select where to pour.','Pour onto the same colour, or into an empty tube.','Fill each tube with one colour. Undo and hints are always available.'],tip:'Empty tubes are breathing room. Use them to free a colour.',control:'Select a tube'},blocks:{name:'Peak Blocks',subtitle:'A fresh fit. A satisfying blast.',description:'Fit pieces, clear lines, keep your crystal board open.',tags:['Puzzle','Block blast'],steps:['Tap a piece in the tray to select it.','Tap the board square for its top-left block. Arrow keys and Enter work too.','Fill a row or column to blast it away. Bomb, Undo, Shuffle and Hint each have 3 uses per run.'],tip:'Keep space for the bigger pieces. The glowing preview shows a valid fit.',control:'Place a piece'},mahjong:{name:'Bottle Mahjong',subtitle:'Find a pair. Reveal a little more of the garden.',description:'Match open pairs in a layered bottle puzzle.',tags:['Puzzle','Pair match'],steps:['Choose a tile with nothing on top and at least one open side.','Tap an identical open tile to remove the pair.','Clear all 17 pairs. Hint, Undo and Shuffle each have 3 uses per board.'],tip:'Hints choose a pair that keeps a route to the finish.',control:'Match a pair'}};
const badges=[{id:'first',name:'A fresh start',text:'Complete your first game.',symbol:'leaf'},{id:'tower10',name:'Peak performer',text:'Stack 10 vials in one run.',symbol:'trophy'},{id:'perfect5',name:'Perfectly placed',text:'Make 5 perfect drops.',symbol:'spark'},{id:'merge5',name:'Mixing magic',text:'Create a tier 5 vial.',symbol:'star'},{id:'sort1',name:'Clear mind',text:'Complete a Lab Sort level.',symbol:'check'},{id:'daily',name:'Daily delight',text:'Complete a daily challenge.',symbol:'flag'}];
function save(){try{localStorage.setItem('ph-arcade-v1',JSON.stringify(data));}catch{toast('Progress could not be saved. You can still keep playing.');}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function earn(id){if(data.badges.includes(id))return false;data.badges.push(id);return true;}
function streak(){let count=0,date=new Date();if(!data.days.includes(localDay(date)))date.setDate(date.getDate()-1);while(data.days.includes(localDay(date))){count++;date.setDate(date.getDate()-1);}return count;}
function sound(type){if(!data.sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);const n=audio.currentTime;o.type='sine';o.frequency.setValueAtTime({drop:420,perfect:750,merge:580,win:880,miss:190}[type]||500,n);o.frequency.exponentialRampToValueAtTime(type==='miss'?100:950,n+.12);g.gain.setValueAtTime(.06,n);g.gain.exponentialRampToValueAtTime(.001,n+.24);o.start(n);o.stop(n+.25);}catch{/* Audio is optional. */}}
function logo(){return `<img class="ph-logo" src="assets/ph-arcade-logo.webp" alt="PH Arcade">`;}
function currency(){return `<div class="player-pills"><button class="currency coin" data-wallet aria-label="${data.coins} coins. View rewards">${icon('coin')}<b>${fmt(data.coins)}</b><span>+</span></button><button class="currency gem" data-wallet aria-label="${data.gems} gems. View rewards">${icon('gem')}<b>${fmt(data.gems)}</b><span>+</span></button><button class="icon-button settings-button" data-settings aria-label="Open settings">${icon('settings')}</button></div>`;}
function shell(content,selected='home'){app.innerHTML=`<div class="phone-app view-${selected} ${selected==='game'?'in-game':''}">${selected==='game'?'':`<header class="app-header"><a class="brand" href="#home" aria-label="PH Arcade home">${logo()}</a>${currency()}</header>`}<main>${content}</main>${selected==='game'?'':`<nav class="bottom-nav" aria-label="Main navigation">${[['home','home','Home'],['arcade','games','Arcade'],['journey','gift','Rewards'],['collection','bottle','Bottles'],['profile','user','Profile']].map(([id,s,label])=>`<button data-nav="${id}" class="${selected===id?'active':''}" ${selected===id?'aria-current="page"':''}>${icon(s)}<span>${label}</span></button>`).join('')}</nav>`}</div>`;document.body.classList.toggle('motion-off',!data.motion);app.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));app.querySelectorAll('[data-wallet]').forEach(b=>b.onclick=()=>navigate('journey'));$('[data-settings]')?.addEventListener('click',openSettings);$('.brand')?.addEventListener('click',e=>{e.preventDefault();navigate('home');});}

function gameArt(type){return `<div class="game-art cover-art cover-${type}" role="img" aria-label="${games[type].name} colourful 3D alpine game artwork"></div>`;}
function currentMission(){return MISSIONS.find(m=>!data.completed.includes(m.id))||MISSIONS.at(-1);}
function renderHome(){view='home';const next=currentMission();const dailyTarget=10,done=Math.min(data.mergeDay===localDay()?data.mergeToday||0:0,dailyTarget);shell(`<section class="home-hero"><div class="hero-copy"><h1>SMALL<br>BOTTLES.<br><em>BIG FUN.</em></h1><p>Casual games, collectible bottles,<br>and a world of play at Peak Haven.</p><button class="button hero-play" data-nav="arcade">${icon('play')}Play Now</button></div>${mascot()}<span class="hero-star star-a">${icon('star')}</span><span class="hero-star star-b">${icon('star')}</span></section><section class="home-content"><div class="category-tabs" aria-label="Choose game category"><button class="active" data-category="all">${icon('games')}All Games</button><button data-category="puzzle">${icon('leaf')}Puzzle</button><button data-category="casual">${icon('star')}Casual</button></div><div class="section-heading"><h2>Popular Games</h2><button class="text-button" data-nav="freeplay">See All ${icon('arrow')}</button></div><div class="popular-row">${Object.entries(games).map(([id,g])=>`<button class="popular-game" data-play="${id}" data-kind="${['sort','blocks','mahjong'].includes(id)?'puzzle':'casual'}">${gameArt(id)}<span class="mini-play">${icon('play')}</span><h3>${g.name}</h3><p>${id==='tower'?'Stack. Balance.<br>Reach the top!':id==='merge'?'Merge bottles.<br>Discover new ones!':id==='sort'?'Sort, match, and<br>clear the lab!':id==='blocks'?'Fit. Clear.<br>Blast the blocks!':'Find pairs.<br>Reveal the garden!'}</p></button>`).join('')}</div><div class="section-heading"><h2>Daily Picks</h2><button class="text-button" data-nav="journey">Rewards ${icon('arrow')}</button></div><button class="daily-pick" data-play="merge"><div><span>Today's Challenge</span><h2>Merge 10 Bottles</h2><p>${done>=10?'Challenge complete! Open Rewards.':'Win a special reward!'}</p><div class="daily-progress"><i style="transform:scaleX(${done/10})"></i><b>${done} / 10</b></div></div><div class="daily-bottles">${vial(1)}${vial(4)}</div>${icon('arrow')}</button><button class="next-mission" data-nav="arcade">${icon('flag')}<span><b>Continue your climb</b><small>Level ${next.id+1} · ${next.title}</small></span>${icon('arrow')}</button><p class="device-note">Progress saves on this device.</p></section>`,'home');bindPlay();app.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{app.querySelectorAll('[data-category]').forEach(x=>x.classList.toggle('active',x===b));app.querySelectorAll('[data-kind]').forEach(x=>x.hidden=b.dataset.category!=='all'&&x.dataset.kind!==b.dataset.category);});}
function renderArcade(){view='arcade';chapter=currentMission().chapter;renderPath();}
function renderPath(){const list=MISSIONS.filter(m=>m.chapter===chapter);let chosen=list.find(m=>!data.completed.includes(m.id))||list.at(-1);shell(`<section class="world-map"><div class="map-title"><h1><span>VIAL</span><br>TOWER</h1><p>CLIMB · COLLECT · CUSTOMIZE</p></div><div class="map-mascot">${mascot()}</div><aside class="map-actions"><button id="map-daily">${icon('gift')}<span>DAILY<br>BONUS</span>${data.claimDay!==localDay()?'<i class="notice-dot"></i>':''}</button><button id="map-spin">${icon('restart')}<span>LUCKY<br>SPIN</span></button><button data-nav="journey">${icon('flame')}<b>${streak()}</b><span>DAY<br>STREAK</span></button></aside><div class="map-track"><svg class="path-line" viewBox="0 0 400 720" preserveAspectRatio="none" aria-hidden="true"><path d="M200 630 C350 570 360 540 260 490 S90 410 165 350 S360 260 280 210 S120 135 215 85"/></svg>${list.map((m,i)=>{const done=data.completed.includes(m.id),open=unlocked(data.completed,m.id);return `<button class="map-node map-node-${i} ${done?'complete':open?'current':'locked'}" data-mission="${m.id}" ${!open?'disabled':''} aria-label="${done?'Replay':open?'Play':'Locked'} level ${m.id+1}: ${m.title}"><span>${open?m.id+1:icon('lock')}</span>${open?`<div class="node-stars">${stars()}</div>`:''}</button>`;}).join('')}<div class="map-loot loot-one">${vial(1)}</div><button class="map-loot loot-two" data-nav="journey" aria-label="View your reward chest"><img src="assets/reward-chest.webp" alt=""></button></div><div class="map-bottom"><div class="level-preview"><div><span id="level-caption">LEVEL ${chosen.id+1}</span><h2 id="level-title">${chosen.title.toUpperCase()}</h2><p id="level-objective">${objective(chosen)} and reach the top!</p></div><div class="level-preview-art">${gameArt(chosen.game)}</div></div><button class="button big-play" id="map-play" ${unlocked(data.completed,chosen.id)?'':'disabled'}>PLAY ${icon('play')}</button><div class="chapter-switch"><button class="icon-button" id="chapter-prev" aria-label="Previous chapter" ${chapter===0?'disabled':''}>${icon('back')}</button><span>${CHAPTERS[chapter]} · ${chapter+1} / 3</span><button class="icon-button" id="chapter-next" aria-label="Next chapter" ${chapter===2?'disabled':''}>${icon('arrow')}</button></div></div></section>`,'arcade');const choose=m=>{chosen=m;$('#level-caption').textContent=`LEVEL ${m.id+1}`;$('#level-title').textContent=m.title.toUpperCase();$('#level-objective').textContent=objective(m)+' and reach the top!';$('.level-preview-art').innerHTML=gameArt(m.game);$('#map-play').disabled=!unlocked(data.completed,m.id);app.querySelectorAll('[data-mission]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.mission)===m.id));};choose(chosen);app.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>{choose(MISSIONS[Number(b.dataset.mission)]);sound('perfect');});$('#map-play').onclick=()=>startMission(chosen.id);$('#map-daily').onclick=openDaily;$('#map-spin').onclick=openSpin;$('#chapter-prev').onclick=()=>{chapter--;renderPath();};$('#chapter-next').onclick=()=>{chapter++;renderPath();};}
function startMission(id){if(!unlocked(data.completed,id))return;mission=MISSIONS[id];openGame(mission.game,false,mission.game==='sort'?mission.target:null);}
function renderFreeplay(){view='freeplay';shell(`<div class="subpage-heading"><h1>Choose your game</h1><p>Five little adventures. Find your favourite.</p></div><div class="game-grid">${Object.entries(games).map(([id,g])=>`<article class="game-card">${gameArt(id)}<div class="game-info"><h2>${g.name}</h2><p>${g.description}</p><span class="best">${icon('trophy')}${id==='sort'?`Level ${data.sortLevel}`:`Best ${fmt(data.best[id])}`}</span><button class="button" data-play="${id}">${icon('play')}Play</button></div></article>`).join('')}</div>`,'arcade');bindPlay();}
function levelProgress(){const level=Math.floor(data.xp/150)+1;return {level,current:data.xp%150,fraction:(data.xp%150)/150};}
function collectionTiles(compact=false){return SKINS.map((skin,i)=>{const owned=data.skins.includes(skin.id),available=skinUnlocked(data,skin);return `<button class="bottle-tile ${data.skin===skin.id?'equipped':''} ${owned?'owned':'locked'}" data-skin="${skin.id}" aria-label="${skin.name}. ${data.skin===skin.id?'Equipped':owned?'Equip':available?'Unlock':'Locked'}">${vial(i)}<span class="bottle-tile-state">${icon(owned?'check':available?'arrow':'lock')}</span>${compact?'':`<strong>${skin.name}</strong><small>${owned?(data.skin===skin.id?'Equipped':'Tap to equip'):skin.coins?`${skin.coins} coins`:skin.gems?`${skin.gems} gems`:skin.requirement}</small>`}</button>`;}).join('');}
function badgeTiles(){return badges.map((b,i)=>`<article class="badge-item ${data.badges.includes(b.id)?'':'locked'}"><div class="badge-icon badge-${i%4}">${icon(data.badges.includes(b.id)?b.symbol:'lock')}</div><h3>${b.name}</h3><p>${data.badges.includes(b.id)?'Unlocked!':b.text}</p></article>`).join('');}
function renderProfile(){view='profile';const lv=levelProgress();shell(`<section class="profile-backdrop">${mascot()}</section><section class="profile-sheet"><div class="profile-identity"><button class="avatar" data-nav="collection" aria-label="Customize your bottle">${mascot()}</button><div><h1>${escapeText(data.playerName)}</h1><div class="profile-level"><b>Lv ${lv.level}</b><div class="xp-track"><i style="transform:scaleX(${lv.fraction})"></i></div><span>${lv.current} / 150 XP</span></div><p>Collect. Customize. Play!</p></div><button class="icon-button edit-name" id="edit-name" aria-label="Edit player name">${icon('settings')}</button></div><div class="profile-stats">${[['flame',streak(),'DAY STREAK'],['games',data.games,'GAMES PLAYED'],['star',data.badges.length,'ACHIEVEMENTS'],['bottle',data.skins.length,'BOTTLES']].map(([s,n,l])=>`<div>${icon(s)}<b>${n}</b><span>${l}</span></div>`).join('')}</div></section><section class="content-module"><div class="section-heading"><h2>${icon('bottle')}MY BOTTLE COLLECTION</h2><button class="text-button" data-nav="collection">${data.skins.length} / 6 ${icon('arrow')}</button></div><div class="bottle-row">${collectionTiles(true)}</div></section><section class="content-module"><div class="section-heading"><h2>${icon('trophy')}ACHIEVEMENTS</h2><button class="text-button" data-nav="journey">${data.badges.length} / 6 ${icon('arrow')}</button></div><div class="badge-row">${badgeTiles()}</div></section><section class="content-module"><div class="section-heading"><h2>${icon('games')}YOUR GAMES</h2><button class="text-button" data-nav="freeplay">See All ${icon('arrow')}</button></div><div class="recent-row">${Object.entries(games).map(([id,g])=>`<button data-play="${id}">${gameArt(id)}<strong>${g.name}</strong><small>${data.best[id]>0?'Best '+fmt(data.best[id]):'Your first game awaits'}</small></button>`).join('')}</div></section><div class="profile-actions"><button id="profile-settings">${icon('settings')}Settings ${icon('arrow')}</button><button data-nav="collection">${icon('bottle')}Customize ${icon('arrow')}</button><button data-nav="help">${icon('help')}Help ${icon('arrow')}</button></div><p class="device-note">Saved on this device. Game currency has no cash value.</p>`,'profile');$('#profile-settings').onclick=openSettings;$('#edit-name').onclick=editName;bindCollection();bindPlay();}
function renderJourney(){view='journey';const lv=levelProgress(),ready=data.claimDay!==localDay();shell(`<section class="rewards-hero">${mascot()}<img class="chest-hero" src="assets/reward-chest.webp" alt="Open chest overflowing with gems and coins"><div class="reward-speech">PLAY.<br>COLLECT.<br>EARN BIG!</div></section><div class="rewards-content"><section class="progress-module"><div class="level-shield"><small>Lv</small><b>${lv.level}</b></div><div><h2>${fmt(data.xp)} XP</h2><div class="xp-track"><i style="transform:scaleX(${lv.fraction})"></i></div><p>${150-lv.current} XP to level ${lv.level+1}</p></div><button class="next-reward" data-nav="collection">${vial(1)}<span>MY BOTTLES<br><b>${data.skins.length} / 6</b></span></button></section><section class="streak-module"><div>${icon('flame')}<b>${streak()} ${streak()===1?'DAY':'DAYS'}</b><p>Play daily to keep your streak!</p></div><div class="streak-calendar">${Array.from({length:7},(_,i)=>`<span class="${i<Math.min(streak(),7)?'done':''}">${icon(i===6?'star':'check')}<small>DAY ${i+1}</small></span>`).join('')}</div></section><section class="daily-chest"><div><h2>${ready?"TODAY’S REWARD<br>IS READY!":"TODAY’S REWARD<br>IS YOURS!"}</h2><p>${ready?'Open your daily chest for<br>coins, gems, and bonus XP.':'Come back tomorrow<br>for another little surprise.'}</p></div><img src="assets/reward-chest.webp" alt="Blue and silver reward chest"><button class="button gold-button" id="daily-open">${icon('gift')}${ready?'OPEN CHEST':'VIEW REWARD'}</button></section><section class="content-module reward-calendar"><div class="section-heading"><h2>REWARD CALENDAR</h2><button class="text-button" id="spin-open">Lucky Spin ${icon('arrow')}</button></div><div class="calendar-row">${Array.from({length:5},(_,i)=>`<button data-reward-day="${i}" class="${i===0?'today':''}"><strong>${i===0?'TODAY':'DAY '+(i+1)}</strong>${i%2===0?vial(i===0?1:i):icon('gem')}<span>${icon('coin')}${50+i*10}</span></button>`).join('')}</div></section><div class="reward-bottom"><section class="content-module"><div class="section-heading"><h2>COLLECTIBLE BADGES</h2></div><div class="badge-row">${badgeTiles()}</div></section><section class="boost-module">${icon('spark')}<h2>2× Coins</h2><p>${data.boostRuns?`${data.boostRuns} games left`:'For your next 5 games'}</p><button class="button" id="boost-open">${data.boostRuns?'BOOST ACTIVE':'USE BOOST'}</button></section></div><p class="device-note">Rewards are in-game collectibles. No purchases required.</p></div>`,'journey');$('#daily-open').onclick=openDaily;$('#spin-open').onclick=openSpin;$('#boost-open').onclick=openBoost;app.querySelectorAll('[data-reward-day]').forEach(b=>b.onclick=()=>Number(b.dataset.rewardDay)===0?openDaily():toast(`Day ${Number(b.dataset.rewardDay)+1}: ${50+Number(b.dataset.rewardDay)*10} coins. Return on consecutive days to grow your daily reward.`));}
function renderCollection(){view='collection';shell(`<section class="collection-hero"><h1>MY BOTTLES</h1><p>Small bottles. Your style.</p>${mascot()}</section><section class="collection-body"><div class="collection-current">${vial(SKINS.findIndex(s=>s.id===data.skin))}<div><h2>${SKINS.find(s=>s.id===data.skin).name}</h2><p>Your equipped bottle.<br>Appears in every Vial Tower run.</p></div></div><div class="section-heading"><h2>Collect. Customize. Play!</h2><span>${data.skins.length} / 6</span></div><div class="collection-grid">${collectionTiles()}</div><button class="button" data-nav="journey">${icon('gift')}Earn more rewards</button><p class="device-note">Earn currency through play. No real-money purchases.</p></section>`,'collection');bindCollection();}
function bindCollection(){app.querySelectorAll('[data-skin]').forEach(b=>b.onclick=()=>openBottle(b.dataset.skin));}
function openBottle(id){const skin=SKINS.find(s=>s.id===id),i=SKINS.indexOf(skin),owned=data.skins.includes(id),available=skinUnlocked(data,skin);showModal(`<button class="icon-button close" id="modal-close" aria-label="Close bottle">${icon('close')}</button><div class="bottle-reveal">${vial(i)}</div><h2 id="dialog-title">${skin.name}</h2><p>${owned?'Make this bottle yours.':skin.requirement}</p><button class="button" id="bottle-action" ${!owned&&!available?'disabled':''}>${owned?(data.skin===id?'Equipped':'Equip bottle'):skin.coins?`Unlock · ${skin.coins} coins`:skin.gems?`Unlock · ${skin.gems} gems`:'Claim bottle'}</button>`);$('#modal-close').onclick=closeModal;$('#bottle-action').onclick=()=>{if(!owned){const bought=buySkin(data,id);if(!bought.ok){toast(bought.reason);return;}data=bought.data;}data.skin=id;save();closeModal();toast(`${skin.name} equipped!`);sound('perfect');if(view==='collection')renderCollection();else if(view==='profile')renderProfile();};}
function openDaily(){const ready=data.claimDay!==localDay();showModal(`<button class="icon-button close" id="modal-close" aria-label="Close daily reward">${icon('close')}</button><div class="chest-reveal"><img src="assets/reward-chest.webp" alt="Daily reward chest"></div><h2 id="dialog-title">${ready?'Your daily reward!':'Reward collected!'}</h2><p>${ready?'A little thank you for stopping by.':'Your chest opens again tomorrow.'}</p><div class="loot-row"><span>${icon('coin')}<b>${ready?dailyCoins():data.lastDailyCoins||50}</b>Coins</span><span>${icon('gem')}<b>+1</b>Gem</span><span>${icon('spark')}<b>+10</b>XP</span></div><button class="button gold-button" id="claim-daily">${ready?'Claim Reward':'Awesome!'}</button>`);$('#modal-close').onclick=closeModal;$('#claim-daily').onclick=()=>{if(ready){const result=claimDaily(data,localDay());if(result.ok){data=result.data;save();closeModal();refreshView();confetti();sound('win');toast('Reward claimed! Coins, gem and XP added.');}}else closeModal();};}
function dailyCoins(){return claimDaily(data,localDay()).coins||data.lastDailyCoins||50;}
function openSpin(){const ready=data.spinDay!==localDay();showModal(`<button class="icon-button close" id="modal-close" aria-label="Close lucky spin">${icon('close')}</button><div class="spin-wheel" id="spin-wheel">${[20,40,1,60,2,30].map((n,i)=>`<span style="--i:${i}">${n}${icon(i===2||i===4?'gem':'coin')}</span>`).join('')}</div><h2 id="dialog-title">A little lucky moment</h2><p>${ready?'One free spin a day. Just for fun.':'Your free spin returns tomorrow.'}</p><button class="button" id="spin-button" ${ready?'':'disabled'}>${ready?'Spin for free':'Already spun today'}</button><p class="modal-footnote">No payment, betting, or cash prizes.</p>`);$('#modal-close').onclick=closeModal;$('#spin-button').onclick=()=>{const result=claimSpin(data,localDay(),Math.random());if(!result.ok)return;data=result.data;save();$('#spin-button').disabled=true;$('#spin-wheel').animate([{transform:'rotate(0deg)'},{transform:`rotate(${1440+result.slot*60}deg)`}],{duration:motionAllowed()?1600:0,easing:'cubic-bezier(.12,.7,.2,1)',fill:'forwards'}).finished.then(()=>{if(!dialog.open||!$('#spin-button'))return;$('#dialog-title').textContent=`You won ${result.amount} ${result.currency}!`;$('#spin-button').textContent='Collect reward';$('#spin-button').disabled=false;$('#spin-button').onclick=()=>{closeModal();refreshView();confetti();};sound('win');});};}
function openBoost(){if(data.boostRuns){toast(`Your 2× coin boost is active for ${data.boostRuns} more games.`);return;}showModal(`<div class="modal-emblem">${icon('spark')}</div><h2 id="dialog-title">Double your game coins</h2><p>2× coins for your next 5 completed games.<br>Unlock with ${boostCost} in-game coins.</p><button class="button" id="boost-buy">Use ${boostCost} coins</button><button class="button secondary" id="boost-cancel">Maybe later</button>`);$('#boost-cancel').onclick=closeModal;$('#boost-buy').onclick=()=>{if(data.coins<boostCost){toast('Play a game or open your daily chest to earn more coins.');return;}data.coins-=boostCost;data.boostRuns=5;save();closeModal();refreshView();toast('2× coin boost activated!');};}
function editName(){showModal(`<h2 id="dialog-title">Your player name</h2><label class="name-label">Name<input id="player-name" maxlength="20" value="${escapeText(data.playerName)}" autocomplete="nickname"></label><button class="button" id="name-save">Save name</button><button class="button secondary" id="name-cancel">Cancel</button>`);$('#name-cancel').onclick=closeModal;$('#name-save').onclick=()=>{const name=$('#player-name').value.trim();if(!name){toast('Enter a player name to continue.');return;}data.playerName=name;save();closeModal();renderProfile();};}
function refreshView(){if(view==='journey')renderJourney();else if(view==='arcade')renderPath();else if(view==='collection')renderCollection();else if(view==='profile')renderProfile();else renderHome();}
function renderHelp(id=helpGame){view='help';helpGame=id;shell(`<div class="view-title"><h1>Easy to learn. Lovely to play.</h1><p>A few simple steps, then you’re on your way.</p></div><div class="help-tabs" role="tablist" aria-label="Game instructions">${Object.entries(games).map(([k,g])=>`<button role="tab" aria-selected="${k===id}" class="${k===id?'active':''}" data-help-tab="${k}">${g.name}</button>`).join('')}</div><section class="help-content" role="tabpanel"><h2>${games[id].name}</h2><p>${games[id].subtitle}</p>${steps(id)}<div class="help-tip">${games[id].tip}</div><button class="button" data-play="${id}">${icon('play')}Let’s play</button></section>`,'help');app.querySelectorAll('[data-help-tab]').forEach(b=>b.onclick=()=>renderHelp(b.dataset.helpTab));bindPlay();}
function steps(id){return `<ol class="steps">${games[id].steps.map((s,i)=>`<li><span class="step-number">${i+1}</span><span>${s}</span></li>`).join('')}</ol>`;}
function bindPlay(){app.querySelectorAll('[data-play]').forEach(b=>b.onclick=()=>{mission=null;openGame(b.dataset.play);});app.querySelectorAll('[data-how]').forEach(b=>b.onclick=()=>navigate(`help/${b.dataset.how}`));}
function setHash(value){history.replaceState(null,'',`#${value}`);}
function navigate(destination){if(active){openLeave(destination);return;}route(destination);}
function route(destination='home'){stopGame();if(dialog.open)dialog.close();setHash(destination);window.scrollTo(0,0);mission=null;if(destination==='arcade')renderArcade();else if(destination==='collection')renderCollection();else if(destination==='freeplay')renderFreeplay();else if(destination==='profile')renderProfile();else if(destination==='journey')renderJourney();else if(destination.startsWith('help'))renderHelp(destination.split('/')[1]||helpGame);else if(destination.startsWith('mission/')){renderHome();const id=Number(destination.split('/')[1]);if(Number.isInteger(id)&&MISSIONS[id])startMission(id);}else if(destination.startsWith('play/')){renderHome();openGame(destination.split('/')[1]);}else renderHome();}
function showModal(content,onCancel=()=>{}){if(dialog.open)dialog.close();modalReturn=document.activeElement;cancelModal=onCancel;dialog.innerHTML=`<div class="modal">${content}</div>`;dialog.showModal();}
function closeModal(){dialog.close();cancelModal=()=>{};if(modalReturn?.isConnected)modalReturn.focus();}
dialog.addEventListener('cancel',e=>{e.preventDefault();const cb=cancelModal;closeModal();cb();});
function openSettings(){const wasPlaying=active&&engine&&!engine.paused;if(wasPlaying)engine.pause(true);const resume=()=>{if(wasPlaying)engine?.pause(false);};showModal(`<button class="icon-button close" id="modal-close" aria-label="Close settings">${icon('close')}</button><h2 id="dialog-title">Make yourself comfortable.</h2><p>Little adjustments for your kind of play.</p><label class="settings-row"><div><strong>Gentle game sounds</strong><small>A little chime for your little wins.</small></div><input id="sound-setting" type="checkbox" ${data.sound?'checked':''}></label><label class="settings-row"><div><strong>Decorative motion</strong><small>Switch off floating clouds and confetti.</small></div><input id="motion-setting" type="checkbox" ${data.motion?'checked':''}></label><p class="modal-footnote">Game movement stays on so you can play.<br>Your preferences stay on this device.</p><button class="button" id="settings-done">All set ${icon('check')}</button>`,resume);$('#sound-setting').onchange=e=>{data.sound=e.target.checked;save();if(data.sound)sound('perfect');};$('#motion-setting').onchange=e=>{data.motion=e.target.checked;document.body.classList.toggle('motion-off',!data.motion);if(engine)engine.motion=motionAllowed();save();};const done=()=>{closeModal();resume();};$('#settings-done').onclick=done;$('#modal-close').onclick=done;}
function openGame(id,forceTutorial=false,level=null){if(!games[id])return route('home');if(engine||active)stopGame();if(!data.tutorials.includes(id)||forceTutorial){showModal(`<button class="icon-button close" id="modal-close" aria-label="Close tutorial">${icon('close')}</button><div class="modal-art">${[0,id==='merge'?1:0,id==='sort'?3:0].map(vial).join('')}</div><h2 id="dialog-title">${games[id].name}</h2><p>${games[id].subtitle}</p>${steps(id)}<button class="button" id="begin-game">${icon('play')}Let’s play</button><p class="modal-footnote">No timer. No pressure. Just enjoy.</p>`,()=>{if(view==='game')route('home');});$('#modal-close').onclick=()=>{closeModal();if(view==='game')route('home');};$('#begin-game').onclick=()=>{closeModal();if(!data.tutorials.includes(id)){data.tutorials.push(id);save();}beginGame(id,level);};}else beginGame(id,level);}
let loadTicket=0;
const gameAssets={tower:['tower-scene','happy-vials','collectible-vials'],merge:['crystal-scene','happy-vials','merge-chamber'],sort:['garden-scene','sort-glass'],blocks:['crystal-scene','game-tiles'],mahjong:['garden-scene','game-tiles','happy-vials']};
const imageCache=new Map();
function preloadImage(name){if(!imageCache.has(name))imageCache.set(name,new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>img.decode().then(resolve,resolve);img.onerror=()=>{imageCache.delete(name);reject(new Error(name));};img.src=`assets/${name}.webp`;}));return imageCache.get(name);}
async function beginGame(id,level=null){const ticket=++loadTicket;view='loading';setHash(mission?`mission/${mission.id}`:`play/${id}`);window.scrollTo(0,0);shell(`<section class="game-loading" aria-labelledby="loading-title"><div class="loading-brand">${logo()}</div>${mascot()}<div class="loading-copy"><div class="loading-track" role="progressbar" aria-label="Game assets loaded" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><i id="loading-fill"></i></div><h1 id="loading-title">Loading ${games[id].name}…</h1><p id="loading-status">Preparing your lab adventure</p><button class="text-button" id="loading-cancel">${icon('close')}Back to arcade</button></div></section>`,'game');$('#loading-cancel').onclick=()=>route('freeplay');const started=performance.now(),assets=gameAssets[id];let complete=0;try{await Promise.all(assets.map(async name=>{await preloadImage(name);if(ticket!==loadTicket)return;complete++;$('#loading-fill').style.transform=`scaleX(${complete/assets.length})`;$('.loading-track').setAttribute('aria-valuenow',Math.round(complete/assets.length*100));}));await document.fonts.ready;await new Promise(resolve=>setTimeout(resolve,Math.max(0,(motionAllowed()?750:150)-(performance.now()-started))));if(ticket===loadTicket&&view==='loading')mountGame(id,level);}catch{if(ticket!==loadTicket)return;$('#loading-status').textContent='The artwork couldn’t load. Check your connection and try again.';$('#loading-title').textContent='Almost there';$('#loading-cancel').insertAdjacentHTML('beforebegin','<button class="button" id="loading-retry">Try again</button>');$('#loading-retry').onclick=()=>beginGame(id,level);}}
function gameTools(list){return `<div class="game-tools">${list.map(([id,label,symbol])=>`<button class="tool-button" data-tool="${id}" aria-label="${label}">${icon(symbol)}<b>3</b><span>${label}</span></button>`).join('')}</div>`;}
function mountGame(id,level=null){active=id;finishing=false;view='game';const g=games[id],isPuzzle=id==='blocks'||id==='mahjong';shell(`<section class="game-world scene-${id}"><div class="game-head"><button class="icon-button" id="game-back" aria-label="Back to arcade">${icon('close')}</button><div><h1>${g.name}</h1><small>${mission?`STEP ${mission.id+1} · ${mission.xp} XP`:id==='blocks'?'BLOCK BLAST':id==='mahjong'?'PAIR MATCH':'FREE PLAY'}</small></div><button class="icon-button" id="game-pause" aria-label="Pause game">${icon('pause')}</button></div><div class="hud"><div>${icon('star')}<span><small>${id==='sort'?'LEVEL':'SCORE'}</small><strong id="hud-score">0</strong></span></div><div>${icon(id==='blocks'?'games':'bottle')}<span><small>${id==='tower'?'VIALS':id==='merge'?'TOP TIER':id==='blocks'?'LINES':id==='mahjong'?'PAIRS LEFT':'MOVES'}</small><strong id="hud-detail">0</strong></span></div><div>${icon(id==='sort'?'trophy':'flame')}<span><small>${id==='sort'?'BEST':'COMBO'}</small><strong id="hud-combo">0</strong></span></div></div><div class="mission-objective"><strong>${mission?objective(mission):id==='blocks'?'Fill a row or column to clear it.':id==='mahjong'?'Match identical tiles with an open side.':g.description}</strong><button class="icon-button" id="game-help" aria-label="Game instructions">${icon('help')}</button></div>${mission?'<div class="mission-progress"><i id="mission-fill"></i></div>':''}<section class="play-panel" aria-label="${g.name} game">${id==='sort'?'<div class="sort-board" id="sort-board" aria-label="Sorting tubes"></div><div class="sort-key" id="sort-key"></div><div class="sort-controls"><button class="button secondary" id="sort-undo">'+icon('undo')+'Undo</button><button class="button" id="sort-hint">'+icon('spark')+'Hint</button><button class="button secondary" id="sort-restart">'+icon('restart')+'Reset</button></div>':isPuzzle?`<div class="puzzle-stage ${id}">${id==='blocks'?'<div class="block-board" id="block-board" role="grid" aria-label="Block placement board, eight rows and eight columns"></div>':'<div class="mahjong-board" id="mahjong-board" aria-label="Layered matching tiles"></div>'}<div class="impact-label" id="impact-label" aria-hidden="true"></div></div>${id==='blocks'?'<div class="block-tray" id="block-tray" aria-label="Available pieces"></div>':''}${gameTools(id==='blocks'?[['bomb','Bomb','spark'],['undo','Undo','undo'],['shuffle','Shuffle','restart'],['hint','Hint','help']]:[['hint','Hint','help'],['undo','Undo','undo'],['shuffle','Shuffle','restart']])}`:'<div class="canvas-wrap"><canvas id="game-canvas" tabindex="0" role="application" aria-label="'+(id==='tower'?'Vial Tower. Tap or press Space to drop the moving vial.':'Vial Merge. Arrow keys position the vial. Space drops it. Matching tier numbers merge.')+'"></canvas><div class="impact-label" id="impact-label" aria-hidden="true"></div><div class="alignment-cue" id="alignment-cue" aria-hidden="true"></div></div><button class="button game-action" id="game-action">'+icon('play')+'Drop Vial</button>'}<p class="game-message" id="game-message" role="status" aria-live="polite">Ready when you are.</p></section></section>`,'game');$('#game-back').onclick=()=>openLeave('freeplay');$('#game-pause').onclick=()=>pauseGame();$('#game-help').onclick=()=>pauseGame(true);if(id==='sort'){setupSort(level||data.sortLevel);return;}
const cb={aligned:value=>{if($('#alignment-cue'))$('#alignment-cue').textContent=value?'Tap now!':'';$('#game-action')?.classList.toggle('aim-ready',value);},hud:(score,detail,combo)=>{$('#hud-score').textContent=fmt(score);$('#hud-detail').textContent=detail;$('#hud-combo').textContent=combo;},message:m=>{if($('#game-message'))$('#game-message').textContent=m;},sound,ready:value=>{if($('#game-action'))$('#game-action').disabled=!value;},end:result=>finishGame(id,result),effect:(label,kind)=>impact(label,kind),progress:result=>updateObjective(result),place:height=>{updateObjective({height});if(height>=10){earn('tower10');if(!data.daily.includes(localDay())){data.daily.push(localDay());earn('daily');}save();}},topTier:()=>{earn('merge5');save();}};
engine=id==='blocks'?startBlocks($('.game-world'),cb,{motion:motionAllowed()}):id==='mahjong'?startMahjong($('.game-world'),cb,{motion:motionAllowed()}):id==='tower'?new TowerEngine($('#game-canvas'),cb,{motion:motionAllowed(),skin:SKINS.findIndex(s=>s.id===data.skin)}):new MergeEngine($('#game-canvas'),cb,{motion:motionAllowed()});if($('#game-action'))$('#game-action').onclick=()=>engine?.action();}
function updateObjective(result){if(!mission||finishing)return;const amount=progress(mission,result);if($('#mission-fill'))$('#mission-fill').style.transform=`scaleX(${Math.min(1,amount/mission.target)})`;if(amount>=mission.target){finishing=true;const run=engine;run?.pause();setTimeout(()=>{if(engine===run)run?.finish();},550);}}
function impact(label,kind){const el=$('#impact-label');if(!el)return;el.textContent=label;el.className=`impact-label ${kind}`;if(motionAllowed()){el.getAnimations().forEach(a=>a.cancel());el.animate([{opacity:0,transform:'translateY(16px) scale(.65)'},{opacity:1,transform:'translateY(-8px) scale(1.12)',offset:.25},{opacity:1,transform:'translateY(-16px) scale(1)',offset:.65},{opacity:0,transform:'translateY(-44px) scale(1)'}],{duration:1000,easing:'cubic-bezier(.23,1,.32,1)'});$('.canvas-wrap')?.animate([{transform:'translateY(0)'},{transform:'translateY(3px)'},{transform:'translateY(0)'}],{duration:180});}else{el.style.opacity=1;setTimeout(()=>el.style.opacity=0,700);}}
function confetti(){if(!motionAllowed())return;const wrap=document.createElement('div');wrap.className='confetti';wrap.setAttribute('aria-hidden','true');app.append(wrap);for(let i=0;i<42;i++){const p=document.createElement('i');p.style.background=COLORS[i%6];p.style.left=`${Math.random()*100}%`;wrap.append(p);p.animate([{transform:`translateY(-30px) rotate(0deg)`,opacity:1},{transform:`translate(${(Math.random()-.5)*160}px, ${window.innerHeight+50}px) rotate(${Math.random()*720}deg)`,opacity:0}],{duration:1800+Math.random()*1000,delay:Math.random()*350,easing:'cubic-bezier(.2,.5,.5,1)',fill:'forwards'});}setTimeout(()=>wrap.remove(),3200);}

function setupSort(level){sortState={level,initial:createPuzzle(level),tubes:null,selected:null,history:[],moves:0,ended:false};sortState.tubes=sortState.initial.map(t=>[...t]);$('#hud-score').textContent=level;$('#hud-combo').textContent=fmt(data.best.sort);renderTubes();$('#sort-undo').onclick=undoSort;$('#sort-hint').onclick=hintSort;$('#sort-restart').onclick=()=>{showModal(`<h2 id="dialog-title">A fresh start?</h2><p>Restart this puzzle from its original arrangement.</p><button class="button" id="confirm-restart">Restart level</button><button class="button secondary" id="cancel-restart">Keep playing</button>`,()=>{});$('#confirm-restart').onclick=()=>{closeModal();sortState.tubes=sortState.initial.map(t=>[...t]);sortState.history=[];sortState.moves=0;sortState.selected=null;renderTubes();$('#game-message').textContent='A fresh start. Select a tube.';};$('#cancel-restart').onclick=closeModal;};}
function renderTubes(){const focused=document.activeElement?.dataset?.tube;const s=sortState;$('#sort-board').classList.toggle('many-tubes',s.tubes.length>5);$('#sort-board').classList.toggle('dense-tubes',s.tubes.length>6);$('#sort-board').innerHTML=s.tubes.map((t,i)=>`<button class="tube-button ${s.selected===i?'selected':''}" data-tube="${i}" aria-pressed="${s.selected===i}" aria-label="Tube ${i+1}: ${t.length?t.map(c=>COLOR_NAMES[c]).join(', ')+', bottom to top':'empty'}"><span class="tube"><span class="tube-fluid">${t.map(c=>`<span class="liquid" style="--c:${COLORS[c]}">${c+1}</span>`).join('')}</span></span><span class="tube-label">${i+1}</span></button>`).join('');const colors=[...new Set(s.tubes.flat())].sort();$('#sort-key').innerHTML=colors.map(c=>`<span><i style="--c:${COLORS[c]}"></i>${c+1} · ${COLOR_NAMES[c]}</span>`).join('');$('#hud-detail').textContent=s.moves;$('#sort-undo').disabled=!s.history.length;app.querySelectorAll('[data-tube]').forEach(b=>b.onclick=()=>selectTube(Number(b.dataset.tube)));if(focused!==undefined)app.querySelector('[data-tube="'+focused+'"]')?.focus({preventScroll:true});}
function selectTube(index){const s=sortState;if(!s||s.ended||dialog.open)return;if(s.selected===null){if(!s.tubes[index].length){$('#game-message').textContent='Choose a tube with liquid first.';return;}s.selected=index;renderTubes();$('#game-message').textContent=`Tube ${index+1} selected. Choose where to pour.`;return;}if(s.selected===index){s.selected=null;renderTubes();return;}const from=s.selected,next=pour(s.tubes,from,index);if(!next){if(s.tubes[index].length===4)$('#game-message').textContent='That tube is full. Choose another or tap to deselect.';else $('#game-message').textContent='Pour onto the same colour, or into an empty tube.';return;}const pourColor=COLORS[s.tubes[from].at(-1)];s.history.push(s.tubes);s.tubes=next;s.moves++;s.selected=null;renderTubes();animatePour(from,index,pourColor);sound('drop');$('#game-message').textContent='A little closer. Lovely work.';if(isSolved(s.tubes)){s.ended=true;if($('#mission-fill'))$('#mission-fill').style.transform='scaleX(1)';sound('win');setTimeout(()=>{if(active==='sort'&&sortState===s)finishGame('sort',{score:Math.max(100,1200-s.moves*20),level:s.level,moves:s.moves,won:true});},350);}}
function animatePour(from,to,color){if(!motionAllowed())return;const a=$(`[data-tube="${from}"] .tube`),b=$(`[data-tube="${to}"] .tube`);const board=$('#sort-board'),bounds=board.getBoundingClientRect(),ar=a.getBoundingClientRect(),br=b.getBoundingClientRect();const x1=ar.left-bounds.left+ar.width/2,y1=ar.top-bounds.top-5,x2=br.left-bounds.left+br.width/2,y2=br.top-bounds.top+12;const stream=document.createElementNS('http://www.w3.org/2000/svg','svg');stream.setAttribute('class','pour-stream');stream.setAttribute('viewBox',`0 0 ${bounds.width} ${bounds.height}`);stream.innerHTML=`<path d="M${x1} ${y1} Q${(x1+x2)/2} ${Math.min(y1,y2)-40} ${x2} ${y2}" fill="none" stroke="${color}" stroke-width="7" stroke-linecap="round" pathLength="100"/>`;board.append(stream);stream.animate([{opacity:0},{opacity:1,offset:.3},{opacity:0}],{duration:480});setTimeout(()=>stream.remove(),480);a?.animate([{transform:'translateY(-14px) rotate(0)'},{transform:`translateY(-20px) rotate(${to>from?25:-25}deg)`,offset:.4},{transform:'translateY(0) rotate(0)'}],{duration:460,easing:'cubic-bezier(.23,1,.32,1)'});b?.animate([{filter:'brightness(1)'},{filter:'brightness(1.3)',transform:'scale(1.06)',offset:.5},{filter:'brightness(1)',transform:'scale(1)'}],{duration:460});}

function undoSort(){if(!sortState.history.length||sortState.ended)return;sortState.tubes=sortState.history.pop();sortState.moves=Math.max(0,sortState.moves-1);sortState.selected=null;renderTubes();$('#game-message').textContent='One step back. Plenty of room to try again.';}
function hintSort(){if(sortState.ended)return;const move=findHint(sortState.tubes);if(move){sortState.selected=move[0];renderTubes();$('#game-message').textContent=`Try pouring tube ${move[0]+1} into tube ${move[1]+1}.`;}else $('#game-message').textContent='Try undoing a pour to free an empty tube. You can always restart.';}
function stopGame(){loadTicket++;engine?.destroy();engine=null;active=null;sortState=null;}
function pauseGame(instructions=false){if(!active)return;engine?.pause();const id=active;showModal(`<div class="modal-emblem">${icon(instructions?'help':'leaf')}</div><h2 id="dialog-title">${instructions?games[id].name:'Take a little breath.'}</h2>${instructions?steps(id):'<p>Your game is right here when you’re ready.</p>'}<button class="button" id="resume-game">${icon('play')}Keep playing</button>${id!=='sort'?'<button class="button secondary" id="finish-run">Finish this run</button>':''}<button class="button ghost" id="leave-game">Back to arcade</button>`,()=>engine?.pause(false));$('#resume-game').onclick=()=>{closeModal();engine?.pause(false);};if($('#finish-run'))$('#finish-run').onclick=()=>{closeModal();engine?.finish();};$('#leave-game').onclick=()=>openLeave('home');}
function openLeave(destination){engine?.pause();showModal(`<h2 id="dialog-title">Head back to the arcade?</h2><p>This run will end. You can start a fresh game whenever you like.</p><button class="button" id="confirm-leave">Back to ${destination==='journey'?'my journey':destination.startsWith('help')?'instructions':'arcade'}</button><button class="button secondary" id="cancel-leave">Keep playing</button>`,()=>engine?.pause(false));$('#confirm-leave').onclick=()=>{closeModal();route(destination);};$('#cancel-leave').onclick=()=>{closeModal();engine?.pause(false);};}
function finishGame(id,result){if(view==='result')return;const current=mission;engine?.destroy();engine=null;active=null;view='result';data.games++;data.best[id]=Math.max(data.best[id]||0,result.score);const day=localDay();if(!data.days.includes(day))data.days.push(day);if((id==='tower'&&result.height>0)||(id==='merge'&&result.merges>0)||(id==='sort'&&result.won)||(['blocks','mahjong'].includes(id)&&result.won))earn('first');if(id==='tower'){data.height=Math.max(data.height,result.height);data.perfects+=result.perfects;if(data.perfects>=5)earn('perfect5');if(result.height>=10)earn('tower10');}if(id==='merge'){data.tier=Math.max(data.tier,result.tier);if(result.tier>=5)earn('merge5');}if(id==='sort'&&result.won){data.sortWins++;data.sortLevel=Math.max(data.sortLevel,result.level+1);earn('sort1');}const freeWon=id==='tower'?result.height>0:id==='merge'?result.merges>0:!!result.won;const reward=current?award(data.completed,data.xp,current,result):{won:freeWon,gained:freeWon?5:0,xp:data.xp+(freeWon?5:0),completed:data.completed};const firstWin=current&&reward.won&&!data.completed.includes(current.id);data.completed=reward.completed;data.xp=reward.xp;const loot=runLoot(data,reward.won,firstWin);data=loot.data;if(id==='merge'){if(data.mergeDay!==day){data.mergeDay=day;data.mergeToday=0;}data.mergeToday+=result.merges||0;if(data.mergeToday>=10&&!data.daily.includes(day)){data.daily.push(day);earn('daily');data.coins+=40;}}save();const won=reward.won;sound(won?'win':'miss');shell(`<section class="result-screen ${won?'victory':'retry'}"><div class="result-scene"><div class="victory-halo"></div><img src="assets/bottle-mascot.webp" alt="Your cheering bottle mascot"><span class="victory-medal">${icon(won?'trophy':'leaf')}</span><span class="result-star star-one">${icon('spark')}</span><span class="result-star star-two">${icon('spark')}</span></div><h1>${won?'LEVEL COMPLETE!':'LET’S TRY AGAIN!'}</h1>${current?`<span class="result-status">Step ${current.id+1} ${won?'complete':'practice'}</span>`:''}<p>${won?current?'One small win. One step closer to the peak.':'A little play makes a brighter day.':'Take a breath and try the same step again.'}</p><div class="result-details"><div><strong>${fmt(result.score)}</strong><small>Score</small></div><div class="earned-xp"><strong>+${reward.gained}</strong><small>XP earned</small></div><div><strong>${id==='tower'?result.height:id==='merge'?result.merges:result.moves||0}</strong><small>${id==='tower'?'Vials':id==='merge'?'Merges':id==='mahjong'?'Pairs':id==='blocks'?'Placements':'Moves'}</small></div></div>${current&&won?`<div class="unlock-note">${icon('check')}${current.id===17?'All 18 steps complete. You reached the peak!':data.completed.includes(current.id+1)?'Great practice. Keep your momentum.':'Next step unlocked. Keep your momentum.'}</div>`:''}<div class="result-loot">${icon('coin')} +${loot.coins} coins ${loot.gems?icon('gem')+' +'+loot.gems+' gem':''}</div><div class="result-actions"><button class="button" id="result-continue">${icon(won?'arrow':'restart')}${current?(won&&current.id<17?'Next Level':won?'Back to arcade':'Try again'):'Play again'}</button><button class="button secondary" id="result-home">${current?'Back to arcade':'Choose another game'}</button></div></section>`,'game');$('#result-continue').onclick=()=>{if(current){if(won&&current.id<17)startMission(current.id+1);else if(!won)startMission(current.id);else route('home');}else{mission=null;beginGame(id,id==='sort'?result.level+1:null);}};$('#result-home').onclick=()=>route(current?'arcade':'freeplay');if(won)confetti();}

window.addEventListener('keydown',e=>{if(dialog.open||!active)return;if(e.key==='Escape'){e.preventDefault();pauseGame();return;}if(!engine||e.target.closest('button,input,a'))return;if(e.code==='Space'||e.key==='Enter'){e.preventDefault();engine.action?.();}if(active==='merge'&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();engine.move(e.key==='ArrowLeft'?-1:1);}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&active&&!dialog.open)pauseGame();});
window.addEventListener('hashchange',()=>route(location.hash.slice(1)||'home'));
route(location.hash.slice(1)||'home');
